# logstash.conf — pipeline sederhana: baca log NGINX, parse, kirim ke ES
input {
  beats {
    port => 5044
  }
}

filter {
  # Parse access log NGINX jadi field: clientip, verb, request, response, bytes
  grok {
    match => { "message" => "%{COMBINEDAPACHELOG}" }
  }
  date {
    match => [ "timestamp", "dd/MMM/yyyy:HH:mm:ss Z" ]
  }
  mutate {
    convert => { "response" => "integer" "bytes" => "integer" }
  }
}

output {
  elasticsearch {
    hosts => ["http://localhost:9200"]
    index => "logs-nginx-%{+YYYY.MM.dd}"   # index per hari
  }
}
